def assert_role_media_now(testCase, dut, port, role):
    """Assert the media of a PLUGGABLE role NOW — after the operator has (re)fitted the module.

    Module-level on purpose: the frame's lint reads every `self.testSet.<name>` as a device
    handle that init() must bind. Records the verdict on `testCase` and returns True/False,
    because by this point a wrong module is a test-relevant observation the operator can
    correct — unlike at init(), where a missing link is a bench problem.
    """
    import ck_media
    status = dut.cmd('show interface %s status' % port.name)
    ok, why = ck_media.assert_role_media(status, port.name, role)
    if ok:
        testCase.passed('module on %s matches the %r role: %s' % (port.name, role, why))
    else:
        testCase.failed('module on %s does NOT match the %r role: %s' % (port.name, role, why))
    return ok


class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_discover(self, dut, unit=None):
        """Every data link on the DUT, classified by asking the DUT what is fitted in each port.

        `dut` is the switch handle commands go to; `unit` is what owns the ports — the STACK
        when the DUT is in one (its members' [portlink]s all count), else `dut` itself.

        Fixed frame — do not edit or delete. Nothing here is pre-declared (Terrence, 2026-09-21:
        "the information shouldn't require pre-loading variables to know it"). The cables come
        from the bench's own [portlink] section through `get_all_port_links()`; the testbox is
        the far end that is a TestBox; a member of the DUT's own stack is never a partner; and
        the MEDIA of each DUT-side port is read from `show interface <port> status` (its Type
        column) and `show system pluggable` (which cages hold a module). An EMPTY cage has no
        media and is no role — nothing is in it.
        Returns {bucket: [(near_port, far_port, far_device), ...]} for the buckets
        tb / copper (fixed twisted pair) / cusfp (twisted pair in a cage) / fibre / absent / unknown.
        """
        import ck_media
        unit = unit if unit is not None else dut
        members = set(unit.all_members()) if hasattr(unit, 'all_members') else set()
        in_cage = ck_media.pluggable_ports(dut.cmd('show system pluggable'))
        found = {'tb': [], 'copper': [], 'cusfp': [], 'fibre': [], 'absent': [], 'unknown': []}
        for far, pairs in unit.get_all_port_links().items():
            if far in members:
                continue                       # stackport / member cabling is not a data path
            for near, far_port in pairs:
                if isinstance(far, ATTestBox.TestBox):
                    found['tb'].append((near, far_port, far))
                    continue
                if not near.name.startswith('port'):
                    continue                   # an eth0 management link is not a data path
                status = dut.cmd('show interface %s status' % near.name)
                kind = ck_media.classify(ck_media.media_type(status, near.name))
                if kind == ck_media.TWISTED_PAIR:
                    bucket = 'cusfp' if ck_media.is_pluggable(near.name, in_cage) else 'copper'
                elif kind == ck_media.FIBRE:
                    bucket = 'fibre'
                elif kind == ck_media.ABSENT:
                    bucket = 'absent'
                else:
                    bucket = 'unknown'
                found[bucket].append((near, far_port, far))
        # Deterministic order, aggregator members LAST (tb470 sentinel, 2026-09-29):
        # get_all_port_links() walks Stack.members, a SET, so the same bench handed out a
        # different port run to run; and a port in a static-channel-group / channel-group is
        # an aggregator member, where a speed/duplex change on ONE member is an aggregator
        # artefact. Not skipped (the DUT decides; the tester may take the link out of its
        # aggregator for the run) - preferred against, and named in the log and at binding.
        self._ck_lag_ports = set()
        for v in found.values():
            for near, far_port, far in v:
                if near.name.startswith('port') and re.search(
                        r'^\s*(static-)?channel-group\b',
                        dut.cmd('show running-config interface %s' % near.name), re.M):
                    self._ck_lag_ports.add(near.name)

        def _natural(s):
            return [int(t) if t.isdigit() else t for t in re.split(r'(\d+)', s)]

        def _order(link):
            near, far_port, far = link
            return (near.name in self._ck_lag_ports, _natural(near.name),
                    _natural(getattr(far, 'name', 'tb')), _natural(far_port.name))
        for v in found.values():
            v.sort(key=_order)
        self.log('topology discovered on %s: %s' % (dut.name, '; '.join(
            '%s=%s' % (k, ','.join('%s%s<->%s.%s' % (
                n.name, ' [LAG member]' if n.name in self._ck_lag_ports else '',
                getattr(f, 'name', 'tb'), p.name) for n, p, f in v))
            for k, v in found.items() if v) or 'NO data links declared'))
        return found

    def _ck_bind_link(self, setup, dut, role, optional=False):
        """Take ONE discovered link for `role` and bind it: (near_port, far_port, far_device).

        Fixed frame — do not edit or delete. `role` is what the TEST needs — 'tb', 'copper',
        'fibre', 'cusfp' — and the link is whichever discovered cable carries that media, so
        the same script binds on any bench cabled for it while the bench declares nothing
        beyond its [portlink]s. A link is never handed out twice; a copper role takes a copper
        SFP only when no fixed twisted-pair link is left; a partner switch is initialised once
        however many links go to it. A REQUIRED role with no link aborts the suite — "this
        bench cannot host this test" is a bench problem, not a test result. An OPTIONAL
        (pluggable) role returns (None, None, None) and the cases needing it report UNSUPPORTED.
        """
        import ck_media
        buckets = {'tb': ('tb',), 'copper': ('copper', 'cusfp'),
                   'cusfp': ('cusfp',), 'fibre': ('fibre',)}[role]
        for bucket in buckets:
            if not self._ck_topo.get(bucket):
                continue
            near, far_port, far = self._ck_topo[bucket].pop(0)
            if isinstance(far, ATTestBox.TestBox):
                # The testbox end of a data link: any fitted media serves a capture/inject
                # path, but an EMPTY cage on the DUT side is a bench problem — say so now.
                status = dut.cmd('show interface %s status' % near.name)
                ok, why = ck_media.assert_role_media(status, near.name, 'tb')
                if not ok:
                    raise RuntimeError(why)
            else:
                # `far` is the device init_all_devices() already initialised — re-initialising
                # it would build a second object (init_stk) or abort the run (init_tb).
                self._ck_far.setdefault(far.name, far)
                far = self._ck_far[far.name]
            self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
                role, dut.name, near.name, getattr(far, 'name', 'tb'), far_port.name, bucket))
            if near.name in getattr(self, '_ck_lag_ports', ()):
                self.log('WARNING: %s %s is an aggregator member (channel-group in its running-config): '
                         'a speed/duplex change on ONE member is an aggregator artefact, not a port '
                         'result - take it out of the aggregator for the run, or cable a standalone '
                         'link, before trusting this role' % (dut.name, near.name))
            return near, far_port, far
        have = ', '.join('%d %s' % (len(v), k) for k, v in self._ck_topo.items() if v) or 'none'
        why = ("BENCH PROBLEM, not a product defect: no unused %s link on %s (data links "
               "discovered: %s). Cable a %s partner port to the DUT and declare it under "
               "[portlink]." % (role, dut.name, have, role))
        if optional:
            self.log(why + ' This role is OPTIONAL here: the cases needing it report UNSUPPORTED.')
            return None, None, None
        raise RuntimeError(why)

    def init(self, setup):
        # Topology is DISCOVERED through the framework at run time, never declared to this
        # script: the DUT is the framework's `swi_a` slot (its stack, when it is in one), the
        # partners are whatever the bench's [portlink]s cable to it, and which link is copper
        # / fibre / copper-SFP is read from the DUT itself. So the script names no port and no
        # partner, binds correctly on any bench cabled for it, and fails loudly on one that is
        # not. (`swi_a`/`stk_a`: 297/192 corpus lookups; a role-named key appears 0 times.)
        # Every device and link the bench's .setup declares is initialised FIRST, by the
        # framework's own init_all_devices(): get_all_port_links() returns only INITIALISED links
        # and get_stack() is set only by init_stk, so a frame that bound swi_a alone discovered
        # NOTHING — its first hardware run, T33235 on tb470, 2026-09-25, aborted in init() with
        # "no unused copper link". powerOn=False: binding never switches a PDU outlet on (a
        # power-cycle test still has its power objects). tb and swi_a come from the returned
        # device table — init_tb() a second time exits the run.
        _devs = setup.init_all_devices(powerOn=False)
        tb = _devs['tb']
        dut = _devs['swi_a']
        # ART's own shape (103 of 239 suites bind BOTH the stack and the swi_a switch):
        # the STACK owns the ports [portlink] declares per member and is what discovery walks;
        # COMMANDS go to the swi_a member handle, which has cmd()/mode() — the framework's Stack
        # class defines neither, and every VCStack member serves the stack-wide CLI. (2026-09-21
        # to 2026-09-23 the frame rebound `dut` to the Stack, so every command died on a
        # stacked DUT; Terrence: "Copy what they do, because it works.")
        _stk = dut.get_stack()
        dut_stack = _stk                   # initialised above; init_stk() again builds a second Stack
        self.tb = tb
        self.dut = dut
        self.dut_stack = dut_stack
        self._ck_far = {}
        self._ck_topo = self._ck_discover(dut, dut_stack)
        # The TESTBOX data link: the ART shape `(dut.portA, tb.ethA)`. Captures, injected
        # frames and pings happen on `tb.ethA`; `dut.portA` is the DUT port under test
        # at the other end of that cable. REQUIRED: a bench without it aborts here.
        (dut.portA, tb.ethA, _tb) = self._ck_bind_link(setup, dut, 'tb')
        # The FIBRE link (a fitted fibre module), OPTIONAL in the same shape; the flag is
        # `self.fibre_supported`, the far port `fibre_peer.portFibre`. Role-specific far names
        # on purpose: two pluggable links often land on the SAME partner switch, and a shared
        # `.portDut` there would be overwritten by the next binding.
        (dut.portFibre, fibre_port, fibre_peer) = self._ck_bind_link(
            setup, dut, 'fibre', optional=True)
        self.fibre_supported = fibre_peer is not None
        if self.fibre_supported:
            fibre_peer.portFibre = fibre_port
        self.fibre_peer = fibre_peer
        dut.has_fibre_link = self.fibre_supported   # the DUT property its cases gate on
        # The NEIGHBOUR switch on a fixed twisted-pair link, REQUIRED: a partner to negotiate
        # against, a polarity to force, a neighbour table to read. Named `peer`, never `dut`:
        # in ART `dut` is the DUT's own stack handle, and a partner called `dut` made every
        # model read `dut.portA` as the DUT's port (T44297, 2026-09-07).
        (dut.portPeer, peer_port, peer) = self._ck_bind_link(setup, dut, 'copper')
        peer.portDut = peer_port
        self.peer = peer
        # NOT BOUND: dutA.
        # A test binds the DUT plus the partners at the far end of the links it needs. These
        # names were only ever inferred from the vocabulary of the selected fragments, which is
        # not evidence the test needs them — and every unused binding becomes a topology demand
        # a bench has to satisfy for nothing. Needing another partner means the case needs
        # another link role, not a device guessed here.

    def configure(self):
        tb = self.tb
        dut = self.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.fibre_peer          # None when self.fibre_supported is False
        portFibre = dut.portFibre
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: Establish serial console sessions to the DUT and to the link partner switch, erase startup configuration on both and reload so each boots with no explicit port configuration, then wait for the CLI prompt to return.
        # setup: Remove the restrictions on the partner copper port ('no speed' and 'duplex auto' under 'interface <partner port>') to restore a full-capability auto/auto link, wait for the link to come up, and record the baseline negotiated speed, duplex and polarity from 'show interface <port>' on the DUT.
        # setup: Remove the mismatch: issue 'no speed' (and 'duplex auto') on the DUT port and 'no speed' / 'duplex auto' on the partner port, then wait for the auto/auto link to re-establish.
        # Restore both ends of the copper link to auto/auto. The frame has already booted both
        # devices with the startup configuration the suite starts from, so only port settings are reset.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.mode('#')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.mode('#')
        # Wait for the auto/auto link to come up, then record the baseline negotiated values.
        waitForLinkState(self, dut, portPeer, 'connected', timeout=60)
        output = dut.cmd('show interface {}'.format(portPeer.name))
        self.baseline_speed = getCurrentValue(output, 'speed')
        self.baseline_duplex = getCurrentValue(output, 'duplex')
        self.baseline_polarity = getCurrentValue(output, 'polarity')
        self.log('Baseline negotiated on {}: speed {}, duplex {}, polarity {}'.format(
            portPeer.name, self.baseline_speed, self.baseline_duplex, self.baseline_polarity))

    def tear_down(self):
        tb = self.tb
        dut = self.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.fibre_peer          # None when self.fibre_supported is False
        portFibre = dut.portFibre
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.cmd('polarity auto')
        dut.mode('#')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.cmd('polarity auto')
        peer.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "On the freshly started DUT with no port configuration applied, run 'show running-config interface <port>' and 'show interface <port>' for a copper test port and for a fibre test port taken from the [portlink] section of the .setup file."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.1'
    testCaseMethod = "On the freshly started DUT with no port configuration applied, run 'show running-config interface <port>' and 'show interface <port>' for a copper test port and for a fibre test port taken from the [portlink] section of the .setup file.\n"
    testCaseMethod += "Verify: No 'speed', 'duplex' or 'polarity' lines are present in the running configuration for either port, confirming auto-negotiation is the default administrative setting; 'show interface <port>' reports the operational result in prose ('current duplex ...', 'current speed ...', 'current polarity ...') separately from the configured setting, and 'show interface status' shows the negotiated values prefixed with 'a-' (e.g. 'a-full', 'a-1000') indicating auto negotiation. Where a media type is not present on the platform, that media is skipped and recorded as not applicable.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The step presumes factory-default port settings: nothing to configure.
        pass

    def main(self):
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1001.py lines 9-31
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 2: On the freshly started DUT with no port configuration applied, run 'show running-config interface <port>' and 'show interface <port>' for a copper test port and for a fibre test port taken from the [portlink] section of the .setup file.")
        dut.mode('#')
        media = [('copper', portPeer)]
        if self.testSet.fibre_supported and portFibre is not None:
            media.append(('fibre', portFibre))
        else:
            self.log('Fibre media not present on this platform: fibre port skipped, recorded as not applicable')
        status_all = dut.cmd('show interface status')
        observed = []
        for label, port in media:
            name = port.name
            run_cfg = dut.cmd('show running-config interface {}'.format(name))
            show_if = dut.cmd('show interface {}'.format(name))
            observed.append('[{} {}]\n{}\n{}'.format(label, name, run_cfg, show_if))
            if checkInvalidCmd(run_cfg) or checkInvalidCmd(show_if):
                self.failed('{} port {}: CLI rejected show command: {}'.format(
                    label, name, (run_cfg + show_if).strip()[:80]))
                continue
            # polarity applies to copper only: fibre has no MDI/MDI-X
            keys = ['duplex', 'speed']
            if label == 'copper':
                keys.append('polarity')
            # 1. no speed/duplex/polarity lines in the running configuration
            bad = [line.strip() for line in run_cfg.splitlines()
                   if line.split()[:1] in (['speed'], ['duplex'], ['polarity'])]
            if bad:
                self.failed('{} port {} running-config has explicit settings {}, expected auto default'.format(
                    label, name, bad))
            else:
                self.passed('{} port {} running-config has no speed/duplex/polarity lines'.format(label, name))
            # 2. operational result reported separately from the configured setting
            cur = [getCurrentValue(show_if, key) for key in keys]
            cfg = [getConfiguredValue(show_if, key) for key in keys]
            missing = [key for key in keys
                       if 'current {}'.format(key) not in show_if or 'configured {}'.format(key) not in show_if]
            if not missing:
                self.passed('{} port {} show interface reports current {} separately from configured {}'.format(
                    label, name, cur, cfg))
            else:
                self.failed('{} port {} show interface lacks current/configured lines for {}'.format(
                    label, name, missing))
            # 3. configured values are auto
            if cfg == ['auto'] * len(keys):
                self.passed('{} port {} configured {} are auto'.format(label, name, '/'.join(keys)))
            else:
                self.failed('{} port {} configured {} are {}, expected auto'.format(
                    label, name, '/'.join(keys), cfg))
            # 4. show interface status shows a- prefixed negotiated values
            row = getStatusRow(status_all, name)
            if not row:
                self.failed('{} port {} missing from show interface status output'.format(label, name))
            elif 'connected' not in row.split():
                self.failed('{} port {} is not connected so negotiated values cannot be read: {}'.format(
                    label, name, row.strip()))
            else:
                tokens = row.split()
                has_duplex = any(tok.startswith('a-') and tok[2:] in ('full', 'half') for tok in tokens)
                has_speed = any(tok.startswith('a-') and tok[2:].isdigit() for tok in tokens)
                if has_duplex and has_speed:
                    self.passed('{} port {} status shows negotiated a- duplex and speed: {}'.format(
                        label, name, row.strip()))
                else:
                    self.failed('{} port {} status row lacks a-duplex/a-speed values: {}'.format(
                        label, name, row.strip()))
        output = '\n'.join(observed) + '\n' + status_all
        self.log('OBSERVED: {}'.format(output))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        # main() only reads state, so nothing to undo; leave the console in exec mode.
        dut.mode('#')


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = "Prompt the operator to install a supported transceiver (from the SVT-agreed list) of the lower supported speed grade into the DUT fibre test port and the matching type into the partner fibre port, connected by fibre patch lead; then poll 'show interface <port> status' until the pluggable is detected and the port state changes."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.2'
    testCaseMethod = "Prompt the operator to install a supported transceiver (from the SVT-agreed list) of the lower supported speed grade into the DUT fibre test port and the matching type into the partner fibre port, connected by fibre patch lead; then poll 'show interface <port> status' until the pluggable is detected and the port state changes.\n"
    testCaseMethod += "Verify: Operator confirms insertion; 'show system pluggable' lists the inserted transceiver on the test port and 'show interface <port> status' transitions to 'connected'.\n"
    testCasePlatformWithPropertyIncl = {'dut': [(['.*'], ['has_fibre_link'])]}
    skipIfExcl = True

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
