class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = "With both DUT and partner fibre ports left at their default auto-negotiation setting (no speed/duplex configured), read 'show interface <port>' and 'show interface status' on both ends."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
