        portFibre = dut.portFibre
        self.log("STEP 8: Prompt the operator to replace the crossover cable with a STRAIGHT-THROUGH copper cable between the same two ports, then poll 'show interface <port> status' until the port reports 'connected'.")
        # PHYSICAL: the operator acts on the hardware, then we poll for the state change.
        port = portPeer
        dut.mode('#')
        # Record the configuration before the swap so we can prove nothing changed.
        before_cfg = dut.cmd('show running-config interface {}'.format(port.name), log=False)
        self.log("OPERATOR: Replace the crossover cable between {} (DUT) and {} (peer) with a STRAIGHT-THROUGH copper cable.".format(
            port.name, portDut.name))
