        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 11: Where the platform supports half duplex, further restrict the LINK PARTNER copper port to advertise only half duplex at a sub-gigabit rate with 'speed auto 100' plus 'duplex half' (half duplex is only valid at 10/100), leave the DUT at auto, and wait for the link to re-establish.")
        import time

        # Probe: does the duplex command accept 'half' on the DUT (and on the partner)?
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        probe_dut = dut.cmd('duplex half')
        dut.cmd('duplex auto')
        dut.mode('#')
