        # PHYSICAL: the operator acts on the hardware, then we poll for the state change.
        port = portPeer
        dut.mode('#')

        # The recorded baseline is the one TestSet.configure() stored from the auto/auto link.
        rec_speed = getattr(self.testSet, 'baseline_speed', None)
