        down_out = dut.cmd('show interface {} status'.format(port.name), log=False)
        self.log('OBSERVED (after unplug): {}'.format(down_out))
        if not went_down:
            self.failed('{} did not report notconnect after the cable was unplugged: {}'.format(
                port.name, getLinkState(down_out, port.name)))
