        self.passed('{} reported notconnect after cable removal'.format(port.name))

        # Phase 2: operator reconnects, port must come back up.
        self.log('OPERATOR: Reconnect the copper cable to DUT port {} now.'.format(port.name))
        if yesNo('Have you reconnected the copper cable to DUT port {}?'.format(port.name)):
            self.passed('Operator confirmed the copper cable was reconnected to {}'.format(port.name))
        else:
            self.failed('Operator did not confirm the copper cable was reconnected to {}'.format(port.name))
            return
        came_up = waitForLinkState(self, dut, port, 'connected', timeout=120)
        output = dut.cmd('show interface {}'.format(port.name))
