class TestCase_12(ATTestCase.TestCase):
    testCaseDesc = "Force re-negotiation administratively: on the DUT enter 'interface <port>', issue 'shutdown', confirm link down, then issue 'no shutdown' and wait for the link to re-establish."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
