    testCaseRef = 'AWPTCM-T33233, 9001.33233.12'
    testCaseMethod = "Force re-negotiation administratively: on the DUT enter 'interface <port>', issue 'shutdown', confirm link down, then issue 'no shutdown' and wait for the link to re-establish.\n"
    testCaseMethod += "Verify: 'show interface <port>' shows the port administratively down then returns to 'Link is UP' after 'no shutdown', with 'current speed', 'current duplex' and 'current polarity' identical to the recorded baseline.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
