class TestCase_14(ATTestCase.TestCase):
    testCaseDesc = "With the auto/auto copper link up and no change made on the DUT, change the LINK PARTNER's advertised capabilities to a different speed grade over its own CLI ('interface <partner port>' then 'speed auto 10', or another rate the port supports that differs from the current negotiated rate), and wait for re-negotiation."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.14'
    testCaseMethod = "With the auto/auto copper link up and no change made on the DUT, change the LINK PARTNER's advertised capabilities to a different speed grade over its own CLI ('interface <partner port>' then 'speed auto 10', or another rate the port supports that differs from the current negotiated rate), and wait for re-negotiation.\n"
    testCaseMethod += "Verify: Without any command entered on the DUT, DUT 'show interface <port>' updates to report the new highest common capability in 'current speed' (e.g. 'current speed 10') with matching 'current duplex', and the partner reports the same values; 'show running-config interface <port>' on the DUT still contains no speed or duplex configuration.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # Establish auto/auto on the DUT and the partner (defaults, via the `no` form).
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.cmd('no shutdown')
        dut.mode('#')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.cmd('no shutdown')
        peer.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0003-CopperSFP_Straight.py lines 595-681
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 16: With the auto/auto copper link up and no change made on the DUT, change the LINK PARTNER's advertised capabilities to a different speed grade over its own CLI ('interface <partner port>' then 'speed auto 10', or another rate the port supports that differs from the current negotiated rate), and wait for re-negotiation.")
        dut.mode('#')
        peer.mode('#')
        # Baseline: link must be up with auto/auto before the partner changes anything.
        if not waitForLinkState(self, dut, portPeer, 'connected', timeout=90):
            self.failed('{} did not reach connected with auto/auto before the partner change'.format(portPeer.name))
            return
        before = dut.cmd('show interface {}'.format(portPeer.name))
        old_speed = getCurrentValue(before, 'speed')
        self.log('Baseline current speed on DUT: {}'.format(old_speed))
        # Choose a lower speed grade the partner accepts (try 100 then 10, skipping the current rate).
        candidates = [rate for rate in ('100', '10') if rate != old_speed]
        new_speed = None
        for rate in candidates:
            peer.mode(')#')
            peer.cmd('interface {}'.format(portDut.name))
            resp = peer.cmd('speed auto {}'.format(rate))
            peer.mode('#')
            if checkInvalidCmd(resp):
                self.log('Partner rejected speed auto {}: {}'.format(rate, resp.strip()[:80]))
                continue
            new_speed = rate
            break
        if new_speed is None:
            self.supported = False
            self.failed('Partner port {} accepts none of speed auto 100 / 10 different from current {}'.format(
                portDut.name, old_speed))
            return
        # Wait for re-negotiation: poll the DUT (read only) until current speed shows the new value.
        output = ''
        dut_speed = None
        for _ in range(30):
            time.sleep(3)
            output = dut.cmd('show interface {}'.format(portPeer.name), log=False)
            dut_speed = getCurrentValue(output, 'speed')
            if dut_speed == new_speed:
                break
        dut_duplex = getCurrentValue(output, 'duplex')
        peer_out = peer.cmd('show interface {}'.format(portDut.name))
        peer_speed = getCurrentValue(peer_out, 'speed')
        peer_duplex = getCurrentValue(peer_out, 'duplex')
        dut_run = dut.cmd('show running-config interface {}'.format(portPeer.name))
        self.log('OBSERVED: {}'.format(output))
        self.log('Partner output: {}'.format(peer_out))
        self.log('DUT running-config: {}'.format(dut_run))
        if dut_speed == new_speed:
            self.passed('DUT current speed updated from {} to {} after partner change, without a DUT command'.format(
                old_speed, dut_speed))
        else:
            self.failed('DUT current speed is {}, expected {} after the partner advertised speed auto {}'.format(
                dut_speed, new_speed, new_speed))
        if dut_duplex is not None and dut_duplex == peer_duplex:
            self.passed('DUT current duplex {} matches partner current duplex {}'.format(dut_duplex, peer_duplex))
        else:
            self.failed('DUT current duplex {} does not match partner current duplex {}'.format(
                dut_duplex, peer_duplex))
        if dut_speed is not None and dut_speed == peer_speed:
            self.passed('Partner reports the same current speed {} as the DUT'.format(peer_speed))
        else:
            self.failed('Partner current speed {} differs from DUT current speed {}'.format(peer_speed, dut_speed))
        cfg_lines = [line.strip() for line in dut_run.splitlines()]
        bad = [line for line in cfg_lines if line.startswith('speed') or line.startswith('duplex')]
        if bad:
            self.failed('DUT running-config for {} contains speed/duplex configuration: {}'.format(
                portPeer.name, bad))
        else:
            self.passed('DUT running-config for {} contains no speed or duplex configuration'.format(
                portPeer.name))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.mode('#')
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.mode('#')


class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = "Restore the partner port to full auto advertisement ('no speed', 'duplex auto'), wait for re-negotiation, and re-read the DUT port state."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.15'
    testCaseMethod = "Restore the partner port to full auto advertisement ('no speed', 'duplex auto'), wait for re-negotiation, and re-read the DUT port state.\n"
    testCaseMethod += "Verify: DUT 'current speed' and 'current duplex' return to the baseline highest common capability with no DUT configuration change, confirming the update is automatic in both directions.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the DUT is left at its defaults (auto/auto), and the partner
        # advertisement is restricted (auto-negotiation kept, as step 16 does) so main() has a
        # real restriction to lift.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('speed auto 100')
        peer.cmd('duplex auto')
        peer.mode('#')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0003-CopperSFP_Straight.py lines 772-857
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 17: Restore the partner port to full auto advertisement ('no speed', 'duplex auto'), wait for re-negotiation, and re-read the DUT port state.")
        # Baseline recorded by TestSet.configure() (highest common capability of the auto/auto link).
        baseline_speed = getattr(self.testSet, 'baseline_speed', None)
        baseline_duplex = getattr(self.testSet, 'baseline_duplex', None)
        if baseline_speed is None or baseline_duplex is None:
            self.supported = False
            self.failed('no baseline speed/duplex was recorded for {}, cannot judge the return to baseline'.format(
                portPeer.name))
            return
        # Observe the DUT while the partner is restricted (the restricted state).
        dut.mode('#')
        waitForLinkState(self, dut, portPeer, 'connected', timeout=60, poll=2)
        restricted = dut.cmd('show interface {}'.format(portPeer.name))
        restricted_speed = getCurrentValue(restricted, 'speed')
        restricted_duplex = getCurrentValue(restricted, 'duplex')
        if restricted_speed == baseline_speed and restricted_duplex == baseline_duplex:
            self.supported = False
            self.failed('partner restriction not effective on {}: current speed {} duplex {} equals the baseline, '
                        'nothing to restore'.format(portPeer.name, restricted_speed, restricted_duplex))
            return
        # Restore the partner to full auto advertisement; the DUT is NOT touched.
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.mode('#')
        waitForLinkState(self, dut, portPeer, 'connected', timeout=60, poll=2)
        # Poll until the DUT reports the baseline again or time runs out.
        speed = None
        duplex = None
        for _ in range(15):
            time.sleep(2)
            output = dut.cmd('show interface {}'.format(portPeer.name), log=False)
            speed = getCurrentValue(output, 'speed')
            duplex = getCurrentValue(output, 'duplex')
            if speed == baseline_speed and duplex == baseline_duplex:
                break
        output = dut.cmd('show interface {}'.format(portPeer.name))
        speed = getCurrentValue(output, 'speed')
        duplex = getCurrentValue(output, 'duplex')
        configured_speed = getConfiguredValue(output, 'speed')
        configured_duplex = getConfiguredValue(output, 'duplex')
        self.log('OBSERVED: baseline speed {} duplex {}; restricted current speed {} duplex {}; '
                 'after restore current speed {} duplex {}; DUT configured speed {} duplex {}'.format(
                     baseline_speed, baseline_duplex, restricted_speed, restricted_duplex,
                     speed, duplex, configured_speed, configured_duplex))
        if speed is None or duplex is None:
            self.failed('current speed/duplex not reported for {} after restoring the partner'.format(portPeer.name))
            return
        if speed == baseline_speed:
            self.passed('DUT {} current speed returned to baseline {} (restricted was {})'.format(
                portPeer.name, speed, restricted_speed))
        else:
            self.failed('DUT {} current speed is {}, expected baseline {}'.format(
                portPeer.name, speed, baseline_speed))
        if duplex == baseline_duplex:
            self.passed('DUT {} current duplex returned to baseline {} (restricted was {})'.format(
                portPeer.name, duplex, restricted_duplex))
        else:
            self.failed('DUT {} current duplex is {}, expected baseline {}'.format(
                portPeer.name, duplex, baseline_duplex))
        if configured_speed == 'auto' and configured_duplex == 'auto':
            self.passed('DUT configuration unchanged: configured speed {}, duplex {}'.format(
                configured_speed, configured_duplex))
        else:
            self.failed('DUT configuration changed: configured speed {}, duplex {}, expected auto/auto'.format(
                configured_speed, configured_duplex))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Mirror configure() and main(): both ends back to the default advertisement.
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        peer.mode('#')
        dut.mode('#')


class TestCase_16(ATTestCase.TestCase):
    testCaseDesc = "Leave the DUT copper port on auto-negotiation (no speed/duplex configured) and FORCE the link partner to a fixed speed and duplex that MATCHES the DUT's maximum copper capability using the bare numeric forms on the partner, e.g. 'interface <partner port>' then 'speed 1000' and 'duplex full' (choosing a rate both ports support). Wait for the link to settle."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.16'
    testCaseMethod = "Leave the DUT copper port on auto-negotiation (no speed/duplex configured) and FORCE the link partner to a fixed speed and duplex that MATCHES the DUT's maximum copper capability using the bare numeric forms on the partner, e.g. 'interface <partner port>' then 'speed 1000' and 'duplex full' (choosing a rate both ports support). Wait for the link to settle.\n"
    testCaseMethod += "Verify: 'show interface <port>' on the DUT reports 'Link is UP' with 'current speed' equal to the partner's forced speed, and the resolved duplex reported in 'current duplex' consistent with the platform's documented fallback rules (typically full at that speed); 'show running-config interface <port>' on the DUT still shows no speed/duplex, proving the DUT resolved rather than was configured.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the DUT copper port is left on auto-negotiation (no speed/duplex).
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 61-85
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 18: Leave the DUT copper port on auto-negotiation (no speed/duplex configured) and FORCE the link partner to a fixed speed and duplex that MATCHES the DUT's maximum copper capability using the bare numeric forms on the partner, e.g. 'interface <partner port>' then 'speed 1000' and 'duplex full' (choosing a rate both ports support). Wait for the link to settle.")
        # DUT stays on auto: make sure nothing is configured on it, and the partner is auto too
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        dut.mode('#')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        peer.mode('#')
        waitForLinkState(self, dut, portPeer, 'connected', timeout=60, poll=2)
        # The auto/auto result is the highest rate both ports support: force the partner to it
        auto_output = dut.cmd('show interface {}'.format(portPeer.name))
        forced_speed = getCurrentValue(auto_output, 'speed')
        if forced_speed is None or not forced_speed.isdigit():
            self.failed('Could not read the auto/auto current speed of {} to choose the forced rate: {}'.format(
                portPeer.name, auto_output.strip()[:120]))
            return
        forced_duplex = 'full'
        # Force the partner using the bare numeric forms
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        speed_response = peer.cmd('speed {}'.format(forced_speed))
        duplex_response = peer.cmd('duplex {}'.format(forced_duplex))
        peer.mode('#')
        if checkInvalidCmd(speed_response) or checkInvalidCmd(duplex_response):
            self.supported = False
            self.failed('Partner {} refused speed {} / duplex {}: {} {}'.format(
                portDut.name, forced_speed, forced_duplex, speed_response.strip()[:80],
                duplex_response.strip()[:80]))
            return
        settled = waitForLinkState(self, dut, portPeer, 'connected', timeout=60, poll=2)
        dut.mode('#')
        output = dut.cmd('show interface {}'.format(portPeer.name))
        run_output = dut.cmd('show running-config interface {}'.format(portPeer.name))
        self.log('OBSERVED: {}\n{}'.format(output, run_output))
        link_up = 'Link is UP' in output
        current_speed = getCurrentValue(output, 'speed')
        current_duplex = getCurrentValue(output, 'duplex')
        if not settled or not link_up:
            self.failed('DUT {} link is not UP after forcing partner to {} {}: {}'.format(
                portPeer.name, forced_speed, forced_duplex, output.strip()[:120]))
            return
        self.passed('DUT {} reports Link is UP with partner forced to {} {}'.format(
            portPeer.name, forced_speed, forced_duplex))
        if current_speed == forced_speed:
            self.passed('DUT {} current speed {} equals the partner forced speed'.format(
                portPeer.name, current_speed))
        else:
            self.failed('DUT {} current speed is {}, expected partner forced speed {}'.format(
                portPeer.name, current_speed, forced_speed))
        if current_duplex == 'full':
            self.passed('DUT {} resolved current duplex {} at {}'.format(
                portPeer.name, current_duplex, forced_speed))
        else:
            self.failed('DUT {} resolved current duplex is {}, expected full at {}'.format(
                portPeer.name, current_duplex, forced_speed))
        run_lines = [line.strip() for line in run_output.splitlines()]
        configured = [line for line in run_lines
                      if line.split()[:1] in (['speed'], ['duplex'])]
        if not configured:
            self.passed('DUT {} running-config shows no speed/duplex, link was resolved not configured'.format(
                portPeer.name))
        else:
            self.failed('DUT {} running-config unexpectedly contains: {}'.format(
                portPeer.name, ', '.join(configured)))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Restore the partner to auto-negotiation and the DUT to its default.
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        peer.cmd('no speed')
        peer.cmd('duplex auto')
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no speed')
        dut.cmd('duplex auto')
        peer.mode('#')
        dut.mode('#')


class TestCase_17(ATTestCase.TestCase):
    testCaseDesc = "Keep the DUT port on auto-negotiation and change the link partner to a DIFFERENT fixed speed from the previous one, e.g. 'speed 100' with 'duplex full' on the partner port, and wait for the link to settle."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.17'
    testCaseMethod = "Keep the DUT port on auto-negotiation and change the link partner to a DIFFERENT fixed speed from the previous one, e.g. 'speed 100' with 'duplex full' on the partner port, and wait for the link to settle.\n"
    testCaseMethod += "Verify: The DUT reports whatever it actually resolved in 'show interface <port>' — link up at 'current speed 100' with the duplex resolved per the platform's fallback rules (parallel detection commonly resolving half duplex where the platform supports half, full otherwise) — and the reported operational values match what the partner reports for speed. The check is that the reported operational values reflect the resolved result and follow the documented fallback rules for the platform, not a fixed speed/duplex pair.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the DUT port presumes factory-default auto-negotiation
        # on both ends of the copper link before the partner is fixed in main().
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0002-CopperFixed_Cross.py lines 702-790
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 19: Keep the DUT port on auto-negotiation and change the link partner to a DIFFERENT fixed speed from the previous one, e.g. 'speed 100' with 'duplex full' on the partner port, and wait for the link to settle.")
        import re
        import time

        def norm(token):
            if token is None:
                return None
            found = re.search(r'\d+', str(token))
            return found.group(0) if found else str(token).strip().lower()

        # DUT stays on auto; fix the partner at 100 / full
        configurePort(self, dut, portPeer, 'speed', 'auto')
        peer.mode(')#')
        peer.cmd('interface {}'.format(portDut.name))
        out_speed = peer.cmd('speed 100')
        out_duplex = peer.cmd('duplex full')
        peer.mode('#')
        if checkInvalidCmd(out_speed) or checkInvalidCmd(out_duplex):
            self.supported = False
            self.failed('{} rejected speed 100 / duplex full on {}: {} {}'.format(
                peer.name, portDut.name, out_speed.strip()[:60], out_duplex.strip()[:60]))
            return

        # Probe whether the DUT platform accepts half duplex (fallback rule for parallel detection)
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        probe = dut.cmd('duplex half')
        half_supported = not checkInvalidCmd(probe)
        dut.cmd('duplex auto')
        dut.mode('#')
        expected_duplex = 'half' if half_supported else 'full'

        # Poll until the link has re-negotiated and the DUT reads current speed 100
        output = ''
        peer_output = ''
        dut_cur_speed = None
        deadline = time.time() + 90
        while True:
            waitForLinkState(self, dut, portPeer, 'connected', timeout=30)
            dut.mode('#')
            peer.mode('#')
            output = dut.cmd('show interface {}'.format(portPeer.name), log=False)
            dut_cur_speed = norm(getCurrentValue(output, 'speed'))
            if dut_cur_speed == '100' or time.time() > deadline:
                break
            time.sleep(3)
        peer_output = peer.cmd('show interface {}'.format(portDut.name))
        output = dut.cmd('show interface {}'.format(portPeer.name))
        dut_cur_speed = norm(getCurrentValue(output, 'speed'))
        dut_cur_duplex = getCurrentValue(output, 'duplex')
        dut_cfg_speed = getConfiguredValue(output, 'speed')
        dut_cfg_duplex = getConfiguredValue(output, 'duplex')
        peer_cur_speed = norm(getCurrentValue(peer_output, 'speed'))
        peer_cur_duplex = getCurrentValue(peer_output, 'duplex')
        self.log('OBSERVED: DUT current speed {} duplex {} (configured speed {} duplex {}); '
                 'partner current speed {} duplex {}; DUT half duplex supported: {}'.format(
                     dut_cur_speed, dut_cur_duplex, dut_cfg_speed, dut_cfg_duplex,
                     peer_cur_speed, peer_cur_duplex, half_supported))

        link_state = getLinkState(dut.cmd('show interface status'), portPeer.name)
        if 'Link is UP' in output and link_state == 'connected':
            self.passed('DUT {} link is up with partner fixed at 100/full'.format(portPeer.name))
        else:
            self.failed('DUT {} link is not up after partner set to speed 100 duplex full (state {}, '
                        'Link is UP reported: {})'.format(portPeer.name, link_state, 'Link is UP' in output))
            return

        if str(dut_cfg_speed).lower() == 'auto' and str(dut_cfg_duplex).lower() == 'auto':
            self.passed('DUT stayed on auto-negotiation (configured speed {}, duplex {})'.format(
                dut_cfg_speed, dut_cfg_duplex))
        else:
            self.failed('DUT configured speed {} duplex {}, expected auto/auto'.format(
                dut_cfg_speed, dut_cfg_duplex))

        if dut_cur_speed == '100':
            self.passed('DUT resolved current speed {}'.format(dut_cur_speed))
        else:
            self.failed('DUT current speed is {}, expected 100'.format(dut_cur_speed))

        duplex_token = str(dut_cur_duplex).lower()
        if duplex_token == expected_duplex:
            self.passed('DUT resolved current duplex {} as expected by the fallback rules '
                        '(half duplex supported on platform: {})'.format(duplex_token, half_supported))
        else:
            self.failed('DUT current duplex is {}, expected {} (half duplex supported on platform: {})'.format(
                dut_cur_duplex, expected_duplex, half_supported))

        if peer_cur_speed == dut_cur_speed:
            self.passed('Partner reports the same current speed {} as the DUT'.format(peer_cur_speed))
        else:
            self.failed('Partner current speed {} does not match DUT current speed {}'.format(
                peer_cur_speed, dut_cur_speed))

        if str(peer_cur_duplex).lower() == 'full':
            self.passed('Partner reports current duplex full, as forced')
        else:
            self.failed('Partner current duplex is {}, expected full as forced'.format(peer_cur_duplex))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: both ends back to default auto.
        configureDefaultPort(self, peer, portDut)
        configureDefaultPort(self, dut, portPeer)
        dut.mode('#')
        peer.mode('#')


