class TestCase_20(ATTestCase.TestCase):
    testCaseDesc = 'Prompt the operator to insert a DIFFERENT supported transceiver type (different capabilities, from the SVT-agreed list) into the DUT fibre port and the matching type at the partner, leaving both ports at auto; poll until the port comes up.'
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.20'
    testCaseMethod = 'Prompt the operator to insert a DIFFERENT supported transceiver type (different capabilities, from the SVT-agreed list) into the DUT fibre port and the matching type at the partner, leaving both ports at auto; poll until the port comes up.\n'
    testCaseMethod += "Verify: 'show system pluggable' reports the new transceiver type; 'show interface <port>' reports 'Link is UP' with 'current speed' and 'current duplex' in line with the newly inserted transceiver's capabilities and matching the partner's reported values.\n"
    testCasePlatformWithPropertyIncl = {'dut': [(['.*'], ['has_fibre_link'])]}
    skipIfExcl = True

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: both fibre ports at auto (speed/duplex defaults).
        if fibre_peer is None or portFibre is None:
            return
        configureDefaultPort(self, dut, portFibre)
        configureDefaultPort(self, fibre_peer, fibre_peer.portFibre)
        dut.mode('#')
        fibre_peer.mode('#')

    def main(self):
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1001.py lines 231-265 (py2→py3)
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log('STEP 23: Prompt the operator to insert a DIFFERENT supported transceiver type (different capabilities, from the SVT-agreed list) into the DUT fibre port and the matching type at the partner, leaving both ports at auto; poll until the port comes up.')
        if not self.testSet.fibre_supported or fibre_peer is None or portFibre is None:
            self.supported = False
            self.failed('No fibre link available on this bench; cannot swap transceiver type')
            return
        import ck_media
        port = portFibre
        pport = fibre_peer.portFibre
        dut.mode('#')
        fibre_peer.mode('#')

        def plug_type(device, portobj):
            # Type column of the 'show system pluggable' row for this port (last token)
            text = device.cmd('show system pluggable', log=False)
            pname = portobj.name
            short = pname[4:] if pname.startswith('port') else pname
            for line in text.splitlines():
                toks = line.split()
                if not toks:
                    continue
                first = toks[0][4:] if toks[0].startswith('port') else toks[0]
                if first == short:
                    return toks[-1]
            return None

        before_type = plug_type(dut, port)
        self.log('Transceiver type before swap: {}'.format(before_type))
        self.log('OPERATOR: Insert a DIFFERENT supported transceiver type (from the SVT-agreed list) into {} on the DUT '
                 'and the matching type into {} on the partner; leave both ports at auto.'.format(port.name, pport.name))
        want = 'connected'
        deadline = time.time() + 300
        output = ''
        state = None
        while time.time() < deadline:
            output = dut.cmd('show interface {} status'.format(port.name), log=False)
            state = getLinkState(output, port.name)
            if state == want:
                break
            self.log('Waiting for operator: swap transceiver on {} / {} and wait for link'.format(port.name, pport.name))
            time.sleep(2)
        full = dut.cmd('show interface {}'.format(port.name))
        plug = dut.cmd('show system pluggable')
        peer_full = fibre_peer.cmd('show interface {}'.format(pport.name))
        new_type = plug_type(dut, port)
        partner_type = plug_type(fibre_peer, pport)
        output = '{}\n{}\n{}\nDUT type {} partner type {}'.format(plug, full, peer_full, new_type, partner_type)
        self.log('OBSERVED: {}'.format(output))

        if state != want:
            self.failed('{} did not reach connected after transceiver swap (state {})'.format(port.name, state))
            return
        self.passed('{} reached connected after the transceiver swap'.format(port.name))

        in_cage = ck_media.pluggable_ports(plug)
        if new_type is None or not ck_media.is_pluggable(port.name, in_cage):
            self.failed('show system pluggable lists no module for {}'.format(port.name))
        elif before_type is not None and new_type == before_type:
            self.failed('transceiver type still {} after swap; a DIFFERENT type was expected'.format(new_type))
        else:
            self.passed('show system pluggable reports new type {} (was {}) on {}'.format(
                new_type, before_type, port.name))

        if 'Link is UP' in full:
            self.passed('show interface {} reports Link is UP'.format(port.name))
        else:
            self.failed('show interface {} does not report Link is UP'.format(port.name))

        cur_speed = getCurrentValue(full, 'speed')
        cur_duplex = getCurrentValue(full, 'duplex')
        peer_speed = getCurrentValue(peer_full, 'speed')
        peer_duplex = getCurrentValue(peer_full, 'duplex')
        if cur_speed is None or cur_duplex is None:
            self.failed('current speed/duplex not presented on {} (speed {}, duplex {})'.format(
                port.name, cur_speed, cur_duplex))
            return
        try:
            max_speed = getPluggableSpeed('', new_type)[0]
        except AssertionError:
            max_speed = None
        if max_speed is None:
            self.failed('cannot derive expected speed from transceiver type {}'.format(new_type))
        elif str(cur_speed) == str(max_speed):
            self.passed('current speed {} matches capability of {}'.format(cur_speed, new_type))
        else:
            self.failed('current speed {} does not match capability {} of {}'.format(cur_speed, max_speed, new_type))
        if str(cur_speed) == str(peer_speed) and str(cur_duplex) == str(peer_duplex):
            self.passed('DUT current speed {} duplex {} match partner'.format(cur_speed, cur_duplex))
        else:
            self.failed('DUT speed {} duplex {} differ from partner speed {} duplex {}'.format(
                cur_speed, cur_duplex, peer_speed, peer_duplex))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Restore both ends to default speed/duplex (auto) — nothing else was changed.
        if fibre_peer is None or portFibre is None:
            return
        configureDefaultPort(self, dut, portFibre)
        configureDefaultPort(self, fibre_peer, fibre_peer.portFibre)
        dut.mode('#')
        fibre_peer.mode('#')


