class TestCase_22(ATTestCase.TestCase):
    testCaseDesc = "After the link-up, link-loss and re-negotiation events exercised above, collect the platform's records for the test ports: 'show log' filtered on the test port, 'show interface <port>', 'show interface status', 'show interface <port> status' and the interface counters from 'show interface <port>' / 'show platform port <port>' where available."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.22'
    testCaseMethod = "After the link-up, link-loss and re-negotiation events exercised above, collect the platform's records for the test ports: 'show log' filtered on the test port, 'show interface <port>', 'show interface status', 'show interface <port> status' and the interface counters from 'show interface <port>' / 'show platform port <port>' where available.\n"
    testCaseMethod += "Verify: The log contains link up and link down entries for the test port matching each transition that was forced (cable removal, shutdown/no shutdown, reload, transceiver removal/insertion); the negotiated speed and duplex reported in the prose 'current speed'/'current duplex' of 'show interface <port>' agree with the 'a-' prefixed values shown in 'show interface status' for the same port, i.e. the negotiated values are reported identically across the available management paths.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # The case forces its own transitions in main(); nothing to pre-configure.
        pass

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0002-CopperFixed_Cross.py lines 2134-2220
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 25: After the link-up, link-loss and re-negotiation events exercised above, collect the platform's records for the test ports: 'show log' filtered on the test port, 'show interface <port>', 'show interface status', 'show interface <port> status' and the interface counters from 'show interface <port>' / 'show platform port <port>' where available.")
        import re
        dut.mode('#')

        # The test ports: the copper link, and the fibre link when the bench has one.
        test_ports = [('copper', portPeer)]
        if self.testSet.fibre_supported and portFibre is not None:
            test_ports.append(('fibre', portFibre))

        # Force one more down/up cycle per test port so the audit always has a fresh transition.
        link_ok = {}
        for role, port in test_ports:
            dut.mode(')#')
            dut.cmd('interface {}'.format(port.name))
            dut.cmd('shutdown')
            dut.mode('#')
            waitForLinkState(self, dut, port, 'notconnect', timeout=30)
            dut.mode(')#')
            dut.cmd('interface {}'.format(port.name))
            dut.cmd('no shutdown')
            dut.mode('#')
            link_ok[role] = waitForLinkState(self, dut, port, 'connected', timeout=90)

        # The buffered log is wiped by a reload, so read the permanent log (fall back to the buffer).
        log_out = dut.cmd('show log permanent')
        if checkInvalidCmd(log_out):
            log_out = dut.cmd('show log')
        status_all = dut.cmd('show interface status')
        collected = ['LOG:\n{}'.format(log_out), 'STATUS ALL:\n{}'.format(status_all)]
        records = {}
        for role, port in test_ports:
            intf_out = dut.cmd('show interface {}'.format(port.name))
            status_port = dut.cmd('show interface {} status'.format(port.name))
            plat_out = dut.cmd('show platform port {}'.format(port.name))
            records[role] = (intf_out, status_port)
            collected.append('{} INTERFACE:\n{}\n{} STATUS:\n{}\n{} PLATFORM:\n{}'.format(
                role, intf_out, role, status_port, role, plat_out))
        output = '\n'.join(collected)
        self.log('OBSERVED: {}'.format(output))

        for role, port in test_ports:
            name = port.name
            short = name[len('port'):] if name.startswith('port') else name
            pattern = re.compile(r'(?<![\w.])(?:port)?{}(?![\w.])'.format(re.escape(short)))
            events = []
            for line in log_out.splitlines():
                if not pattern.search(line):
                    continue
                low = line.lower()
                if re.search(r'\bdown\b', low):
                    events.append('down')
                elif re.search(r'\bup\b', low):
                    events.append('up')
            downs = events.count('down')
            ups = events.count('up')
            if not events:
                self.failed('{} port {}: log has no link up/down entries, so no forced transition was recorded'.format(
                    role, name))
                continue
            self.passed('{} port {}: log has {} link down and {} link up entries'.format(role, name, downs, ups))
            if downs >= 1:
                self.passed('{} port {}: log records link down entries ({}) for the forced loss events'.format(
                    role, name, downs))
            else:
                self.failed('{} port {}: log has no link down entry'.format(role, name))
            if ups >= 1 and ups >= downs:
                self.passed('{} port {}: every link down ({}) is matched by a link up entry ({})'.format(
                    role, name, downs, ups))
            else:
                self.failed('{} port {}: {} link up entries do not match {} link down entries'.format(
                    role, name, ups, downs))
            if events[-1] == 'up':
                self.passed('{} port {}: last logged transition is link up, matching the connected port'.format(
                    role, name))
            else:
                self.failed('{} port {}: last logged transition is {}, expected up'.format(
                    role, name, events[-1]))

            # Negotiated speed/duplex agree between show interface and show interface status.
            if not link_ok.get(role):
                self.failed('{} port {} did not return to connected, cannot compare negotiated values'.format(
                    role, name))
                continue
            intf_out, status_port = records[role]
            cur_speed = getCurrentValue(intf_out, 'speed')
            cur_duplex = getCurrentValue(intf_out, 'duplex')
            row_port = getStatusRow(status_port, name)
            row_all = getStatusRow(status_all, name)
            if row_port is None or row_all is None or cur_speed is None or cur_duplex is None:
                self.failed('{} port {}: current speed {}, current duplex {}, status row {}, status-all row {}: values missing'.format(
                    role, name, cur_speed, cur_duplex, row_port, row_all))
                continue
            for label, line in (('show interface <port> status', row_port), ('show interface status', row_all)):
                tokens = line.split()
                st_duplex = next((t for t in tokens if t.replace('a-', '', 1) in ('full', 'half')), None)
                st_speed = next((t for t in tokens if t.replace('a-', '', 1).isdigit()
                                 and t != tokens[0]), None)
                if st_duplex is None or st_speed is None:
                    self.failed('{} row for {} lacks duplex/speed columns: {}'.format(label, name, line.strip()))
                elif role == 'copper' and not (st_duplex.startswith('a-') and st_speed.startswith('a-')):
                    self.failed('{} row for {} lacks a- prefixed negotiated values: {}'.format(
                        label, name, line.strip()))
                elif (st_duplex.replace('a-', '', 1) == str(cur_duplex)
                      and st_speed.replace('a-', '', 1) == str(cur_speed)):
                    self.passed('{} agrees with show interface for {}: {} {}'.format(
                        label, name, st_duplex, st_speed))
                else:
                    self.failed('{} shows {} {} but show interface current is duplex {} speed {} for {}'.format(
                        label, st_duplex, st_speed, cur_duplex, cur_speed, name))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no shutdown')
        if self.testSet.fibre_supported and portFibre is not None:
            dut.cmd('interface {}'.format(portFibre.name))
            dut.cmd('no shutdown')
        dut.mode('#')


class TestCase_23(ATTestCase.TestCase):
    testCaseDesc = "Record baseline interface error counters and device resource usage on the DUT ('show interface <port>' counters, 'show memory', 'show cpu'), then cycle the COPPER link through negotiation repeatedly over a sustained run by issuing 'shutdown' / 'no shutdown' on the DUT copper port for a large number of iterations, reading 'show interface <port>' after each cycle."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.23'
    testCaseMethod = "Record baseline interface error counters and device resource usage on the DUT ('show interface <port>' counters, 'show memory', 'show cpu'), then cycle the COPPER link through negotiation repeatedly over a sustained run by issuing 'shutdown' / 'no shutdown' on the DUT copper port for a large number of iterations, reading 'show interface <port>' after each cycle.\n"
    testCaseMethod += "Verify: On every iteration the link returns to 'Link is UP' with the same 'current speed', 'current duplex' and 'current polarity' as the baseline; between iterations the port does not report additional unexpected link transitions in 'show log'; interface error counters show no growth beyond baseline and 'show memory' / 'show cpu' do not trend upward across the run.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        # Start from a known state: copper port administratively up, defaults restored.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no shutdown')
        dut.mode('#')

    def main(self):
        # ART 6000_link_check/test-6000.7001-memory.py lines 70-154
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 26: Record baseline interface error counters and device resource usage on the DUT ('show interface <port>' counters, 'show memory', 'show cpu'), then cycle the COPPER link through negotiation repeatedly over a sustained run by issuing 'shutdown' / 'no shutdown' on the DUT copper port for a large number of iterations, reading 'show interface <port>' after each cycle.")
        import re
        iterations = 50
        port = portPeer
        pname = port.name

        def err_counters(text):
            # sum every counter on a line mentioning errors/drops/collisions/CRC
            total = 0
            for ln in text.splitlines():
                low = ln.lower()
                if 'error' in low or 'crc' in low or 'collision' in low or 'dropped' in low:
                    if 'dropped' in low and 'error' not in low and 'crc' not in low:
                        # "input packets N, bytes N, dropped N" - count only the dropped value
                        m = re.search(r'dropped\s+(\d+)', low)
                        total += int(m.group(1)) if m else 0
                    else:
                        total += sum(int(x) for x in re.findall(r'\b(\d+)\b', ln))
            return total

        def free_mem(text):
            m = re.search(r'free:\s*(\d+)', text)
            return int(m.group(1)) if m else None

        def cpu_60(text):
            m = re.search(r'60 seconds:\s*(\d+)%', text)
            return int(m.group(1)) if m else None

        def link_log_count(text):
            return sum(1 for ln in text.splitlines()
                       if pname in ln and ('link' in ln.lower() or 'up' in ln.lower() or 'down' in ln.lower()))

        dut.mode('#')
        base_if = dut.cmd('show interface {}'.format(pname))
        base_speed = getCurrentValue(base_if, 'speed')
        base_duplex = getCurrentValue(base_if, 'duplex')
        base_pol = getCurrentValue(base_if, 'polarity')
        base_err = err_counters(base_if)
        base_mem = free_mem(dut.cmd('show memory'))
        base_cpu = cpu_60(dut.cmd('show cpu'))
        self.log('BASELINE: {} speed={} duplex={} polarity={} errors={} free_mem={} cpu60={}'.format(
            pname, base_speed, base_duplex, base_pol, base_err, base_mem, base_cpu))

        if 'Link is UP' not in base_if or base_speed is None or base_duplex is None:
            output = base_if
            self.log('OBSERVED: {}'.format(output))
            self.failed('{} not UP with readable current speed/duplex at baseline: {}'.format(
                pname, base_if.strip()[:120]))
            return

        dut.cmd('clear log buffered', log=False)
        mismatches = []
        down_iters = []
        no_drop_iters = []
        mem_samples = []
        cpu_samples = []
        last_if = base_if
        for i in range(iterations):
            dut.mode(')#')
            dut.cmd('interface {}'.format(pname), log=False)
            dut.cmd('shutdown', log=False)
            dut.mode('#')
            # Confirm the link really dropped, so a renegotiation is forced each cycle
            dropped = waitForLinkState(self, dut, port, 'notconnect', timeout=30, poll=1)
            if not dropped:
                dropped_if = dut.cmd('show interface {}'.format(pname), log=False)
                dropped = 'Link is DOWN' in dropped_if
            if not dropped:
                no_drop_iters.append(i + 1)
            dut.mode(')#')
            dut.cmd('interface {}'.format(pname), log=False)
            dut.cmd('no shutdown', log=False)
            dut.mode('#')
            up = waitForLinkState(self, dut, port, 'connected', timeout=60, poll=2)
            last_if = dut.cmd('show interface {}'.format(pname), log=False)
            if not up or 'Link is UP' not in last_if:
                down_iters.append(i + 1)
                continue
            cur = (getCurrentValue(last_if, 'speed'), getCurrentValue(last_if, 'duplex'),
                   getCurrentValue(last_if, 'polarity'))
            if cur != (base_speed, base_duplex, base_pol):
                mismatches.append((i + 1, cur))
            if (i + 1) % 10 == 0:
                mem_samples.append(free_mem(dut.cmd('show memory', log=False)))
                cpu_samples.append(cpu_60(dut.cmd('show cpu', log=False)))

        final_log = dut.cmd('show log', log=False)
        final_err = err_counters(last_if)
        output = 'iterations={} down={} never_dropped={} mismatches={} errors {}->{} mem={} cpu={}'.format(
            iterations, down_iters, no_drop_iters, mismatches, base_err, final_err, mem_samples, cpu_samples)
        self.log('OBSERVED: {}'.format(output))

        # Each cycle really took the link down (renegotiation happened)
        if no_drop_iters:
            self.failed('{} never reported link down after shutdown on iterations {}, no renegotiation forced'.format(
                pname, no_drop_iters))
        else:
            self.passed('{} dropped link after shutdown on all {} iterations'.format(pname, iterations))

        # Link returns UP on every iteration
        if down_iters:
            self.failed('{} did not return to Link is UP on iterations {}'.format(pname, down_iters))
        else:
            self.passed('{} returned to Link is UP on all {} iterations'.format(pname, iterations))

        # Same current speed/duplex/polarity as baseline
        if mismatches:
            self.failed('{} current speed/duplex/polarity differed from baseline ({}, {}, {}): {}'.format(
                pname, base_speed, base_duplex, base_pol, mismatches[:5]))
        else:
            self.passed('{} kept current speed {}, duplex {}, polarity {} on every iteration'.format(
                pname, base_speed, base_duplex, base_pol))

        # No unexpected link transitions in the log beyond the ones we caused (2 per iteration)
        transitions = link_log_count(final_log)
        if transitions > iterations * 2:
            self.failed('show log has {} link events for {}, more than the {} expected from {} cycles'.format(
                transitions, pname, iterations * 2, iterations))
        else:
            self.passed('show log has {} link events for {}, within the {} caused by the cycles'.format(
                transitions, pname, iterations * 2))

        # Error counters no growth beyond baseline
        if final_err > base_err:
            self.failed('{} error counters grew from {} to {}'.format(pname, base_err, final_err))
        else:
            self.passed('{} error counters stayed at {} (baseline {})'.format(pname, final_err, base_err))

        # Memory trend: free memory should not fall steadily/substantially
        mem_vals = [m for m in mem_samples if m is not None]
        if base_mem is None or not mem_vals:
            self.failed('show memory free value could not be parsed (baseline {}, samples {})'.format(
                base_mem, mem_samples))
        else:
            drop = base_mem - mem_vals[-1]
            limit = max(int(base_mem * 0.02), 1024)
            if drop > limit:
                self.failed('free memory fell from {} kB to {} kB across the run (limit {} kB)'.format(
                    base_mem, mem_vals[-1], limit))
            else:
                self.passed('free memory {} kB -> {} kB across the run, no upward usage trend'.format(
                    base_mem, mem_vals[-1]))

        # CPU trend: 60 second average should not climb
        cpu_vals = [c for c in cpu_samples if c is not None]
        if base_cpu is None or not cpu_vals:
            self.failed('show cpu 60 second average could not be parsed (baseline {}, samples {})'.format(
                base_cpu, cpu_samples))
        else:
            if cpu_vals[-1] > base_cpu + 10:
                self.failed('CPU 60s average rose from {}% to {}% across the run'.format(
                    base_cpu, cpu_vals[-1]))
            else:
                self.passed('CPU 60s average {}% -> {}% across the run, no upward trend'.format(
                    base_cpu, cpu_vals[-1]))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        dut.cmd('no shutdown')
        dut.mode('#')


class TestCase_24(ATTestCase.TestCase):
    testCaseDesc = "Repeat the sustained negotiation cycling on the FIBRE test port by issuing 'shutdown' / 'no shutdown' on the DUT fibre port for the same number of iterations, reading 'show interface <port>' after each cycle, and re-reading resource usage at the end."
    # ART identity <family>.<case>.<TestCase> — the framework composes the same triple
    # from the filename and this class name, and the run log prints it per case.
    testCaseRef = 'AWPTCM-T33233, 9001.33233.24'
    testCaseMethod = "Repeat the sustained negotiation cycling on the FIBRE test port by issuing 'shutdown' / 'no shutdown' on the DUT fibre port for the same number of iterations, reading 'show interface <port>' after each cycle, and re-reading resource usage at the end.\n"
    testCaseMethod += "Verify: Every cycle re-establishes 'Link is UP' with the same negotiated 'current speed' and 'current duplex' as the fibre baseline for the inserted transceiver; no unexpected flapping appears in 'show log', interface error counters do not grow, and 'show memory' / 'show cpu' show no upward trend across the run.\n"
    testCasePlatformWithPropertyIncl = {'dut': [(['.*'], ['has_fibre_link'])]}
    skipIfExcl = True

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        if fibre_peer is None or portFibre is None:
            return
        dut.mode(')#')
        dut.cmd('interface {}'.format(portFibre.name))
        dut.cmd('no shutdown')
        dut.mode('#')

    def main(self):
        # ART 6000_link_check/test-6000.7001-memory.py lines 70-154
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        self.log("STEP 27: Repeat the sustained negotiation cycling on the FIBRE test port by issuing 'shutdown' / 'no shutdown' on the DUT fibre port for the same number of iterations, reading 'show interface <port>' after each cycle, and re-reading resource usage at the end.")
        if not self.testSet.fibre_supported or portFibre is None:
            self.supported = False
            self.failed('fibre link not available on this bench, cannot cycle the fibre port')
            return
        import re
        import time
        # same iteration count as the copper negotiation cycling run in TestCase_23
        iterations = 50
        name = portFibre.name

        def counters(text):
            # sum of error-ish counters printed by 'show interface' (same quantities as the copper run)
            total = 0
            for line in text.splitlines():
                low = line.lower()
                if 'error' in low or 'crc' in low or 'drop' in low:
                    for num in re.findall(r'(?:errors?|crc|dropped)\D{0,3}(\d+)', low):
                        total += int(num)
            return total

        def mem_free(text):
            found = re.search(r'free:\s*(\d+)', text)
            return int(found.group(1)) if found else None

        def cpu_load(text):
            found = re.search(r'60 seconds:\s*(\d+)%', text)
            return int(found.group(1)) if found else None

        dut.mode('#')
        if not waitForLinkState(self, dut, portFibre, 'connected', timeout=60):
            self.failed('fibre port {} did not reach connected before cycling'.format(name))
            return
        base = dut.cmd('show interface {}'.format(name))
        base_speed = getCurrentValue(base, 'speed')
        base_duplex = getCurrentValue(base, 'duplex')
        base_errors = counters(base)
        mem_before = mem_free(dut.cmd('show memory'))
        cpu_before = cpu_load(dut.cmd('show cpu'))
        log_before = dut.cmd('show log')
        log_before_len = len(log_before.splitlines())
        self.log('Baseline {}: speed {}, duplex {}, errors {}, free mem {}, cpu60 {}'.format(
            name, base_speed, base_duplex, base_errors, mem_before, cpu_before))

        bad_cycles = []
        last_output = base
        for count in range(1, iterations + 1):
            dut.mode(')#')
            dut.cmd('interface {}'.format(name))
            dut.cmd('shutdown')
            time.sleep(2)
            dut.cmd('no shutdown')
            dut.mode('#')
            up = waitForLinkState(self, dut, portFibre, 'connected', timeout=60)
            last_output = dut.cmd('show interface {}'.format(name))
            speed = getCurrentValue(last_output, 'speed')
            duplex = getCurrentValue(last_output, 'duplex')
            if not up or 'Link is UP' not in last_output:
                bad_cycles.append('cycle {}: link not UP'.format(count))
            elif speed != base_speed or duplex != base_duplex:
                bad_cycles.append('cycle {}: speed {} duplex {}, baseline speed {} duplex {}'.format(
                    count, speed, duplex, base_speed, base_duplex))

        end_errors = counters(last_output)
        mem_after = mem_free(dut.cmd('show memory'))
        cpu_after = cpu_load(dut.cmd('show cpu'))
        log_after = dut.cmd('show log')
        new_log = log_after.splitlines()[log_before_len:] if len(log_after.splitlines()) >= log_before_len else []
        flap_lines = [line for line in new_log if name in line and
                      ('link' in line.lower() or 'state' in line.lower())]
        # each cycle legitimately logs a down and an up; anything beyond that is unexpected flapping
        expected_events = iterations * 2 + 4
        output = ('cycles {}, bad {}, errors {}->{}, free mem {}->{}, cpu60 {}->{}, '
                  'link log lines {}').format(iterations, bad_cycles, base_errors, end_errors,
                                              mem_before, mem_after, cpu_before, cpu_after, len(flap_lines))
        self.log('OBSERVED: {}'.format(output))

        if base_speed is None or base_duplex is None:
            self.failed('could not read baseline current speed/duplex for {}'.format(name))
            return

        if not bad_cycles:
            self.passed('all {} cycles on {} re-established Link is UP with current speed {} and duplex {}'.format(
                iterations, name, base_speed, base_duplex))
        else:
            self.failed('{} of {} cycles deviated: {}'.format(len(bad_cycles), iterations, '; '.join(bad_cycles)))

        if len(flap_lines) <= expected_events:
            self.passed('show log shows {} link events for {} across {} cycles, no unexpected flapping'.format(
                len(flap_lines), name, iterations))
        else:
            self.failed('show log shows {} link events for {}, more than the {} expected from {} cycles'.format(
                len(flap_lines), name, expected_events, iterations))

        if end_errors <= base_errors:
            self.passed('{} error counters did not grow (baseline {}, end {})'.format(name, base_errors, end_errors))
        else:
            self.failed('{} error counters grew from {} to {}'.format(name, base_errors, end_errors))

        if mem_before is None or mem_after is None:
            self.failed('could not parse free memory from show memory (before {}, after {})'.format(
                mem_before, mem_after))
        elif mem_before - mem_after > max(2048, mem_before // 50):
            self.failed('free memory fell from {} kB to {} kB across the run'.format(mem_before, mem_after))
        else:
            self.passed('free memory stable across the run ({} kB -> {} kB)'.format(mem_before, mem_after))

        if cpu_before is None or cpu_after is None:
            self.failed('could not parse 60 second CPU average from show cpu (before {}, after {})'.format(
                cpu_before, cpu_after))
        elif cpu_after - cpu_before > 10:
            self.failed('60 second CPU average rose from {}% to {}% across the run'.format(cpu_before, cpu_after))
        else:
            self.passed('CPU average stable across the run ({}% -> {}%)'.format(cpu_before, cpu_after))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        fibre_peer = self.testSet.fibre_peer          # None when self.testSet.fibre_supported is False
        portFibre = dut.portFibre
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        if fibre_peer is None or portFibre is None:
            return
        dut.mode(')#')
        dut.cmd('interface {}'.format(portFibre.name))
        dut.cmd('no shutdown')
        dut.mode('#')


